def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([5]), fmt([-5]), fmt([-3, -3, -3]), fmt([0, 0, 0]), fmt([-1, 0, 0, -1]), fmt([2, 0, -5, 2, 0]),
             fmt([1, -2, 3, 4, -1, 2, -10, 5]), fmt([0, -1, 0]), fmt([3, -3, 3, -3, 3]), fmt([-4, -1, -1])]
    for n in (2, 3, 4, 6, 8, 12, 20, 30):
        for _ in range(3):
            lo = rng.choice([-3, -5, -10])
            hi = rng.choice([3, 5, 10])
            tests.append(fmt([rng.randint(lo, hi) for _ in range(n)]))
    for n in (10, 25, 40):
        tests.append(fmt([rng.choice([0, 0, 0, 1, -1]) for _ in range(n)]))
    N = 100000
    tests.append(fmt([rng.randint(-10**9, 10**9) for _ in range(N)]))
    tests.append(fmt([0] * N))
    tests.append(fmt([rng.choice([0, 0, 0, 1, -1, 2, -2]) for _ in range(N)]))
    tests.append(fmt([10**9, -10**9] * (N // 2)))
    tests.append(fmt([rng.randint(-10**9, 10**9) // 1000 * 1000 if rng.random() < 0.5 else 0 for _ in range(N)]))
    return tests
